@Test fun autoBumpsAndSeparatesReleaseNotesFromHistory() { val task = prepareTask() git("tag", "v0.1.0") assertThrows(IllegalArgumentException::class.java) { task.prepare() } for ((message, version) in listOf("fix: repaired" to "0.1.1", "feat: added" to "0.2.0", "feat!: replaced" to "1.0.0")) { root.resolve("gradle.properties").writeText("modVersion=0.1.0
") git("commit", "--allow-empty", "-qm", message) task.prepare() assertEquals("v$version
", root.resolve(".release/tag").readText()) val notes = root.resolve(".release/notes.md").readText() val full = root.resolve("CHANGELOG.md").readText() assertTrue(message.substringAfter(": ") in notes) assertTrue("initial" !in notes && "initial" in full) assertTrue(notes.trim() in full) } root.resolve("gradle.properties").writeText("modVersion=0.2.0
") assertThrows(IllegalArgumentException::class.java) { task.prepare() } }
